  public int minimumEffortPath(int[][] heights) {
    int left = 0, right = 1_000_000;
    while (left < right) {
      int mid = left + (right - left) / 2;
      boolean[][] seen = new boolean[heights.length][heights[0].length];
      if (canReach(0, 0, mid, heights, seen)) right = mid;
      else left = mid + 1;
    }
    return left;
