  public int minCostConnectPoints(int[][] points) {
    int n = points.length;
    boolean[] used = new boolean[n];
    int[] min = new int[n];
    Arrays.fill(min, Integer.MAX_VALUE);
    min[0] = 0;
    int answer = 0;

    for (int step = 0; step < n; step++) {
